parameters.jsCode:
const agent = $json;
const prep = $('Prepare Application').first().json;
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];
const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]/g, '');
const asText = o => {
  if (o == null) return '';
  if (typeof o === 'string') return o;
  return String(o.output ?? o.text ?? o.response ?? o.result ?? JSON.stringify(o));
};
const grab = name => {
  const hits = steps.filter(s => norm(s?.action?.tool ?? s?.action?.toolName ?? s?.tool) === norm(name));
  return hits.length ? asText(hits[hits.length - 1].observation).replace(/\\n/g, '\n').trim() : '';
};
const parts = {
  'CV Matcher': grab('CV Matcher'),
  'Cover Letter Writer': grab('Cover Letter Writer'),
  'Interview Coach': grab('Interview Coach'),
};
const missing = Object.keys(parts).filter(k => !parts[k]);
const part = k => parts[k] || `_${k} did not return a result. Please submit the form again._`;
const opening = String(agent.output ?? '').trim();
const markdown = [
  `# Your application pack, ${prep.name}`,
  opening,
  '---',
  '## CV match analysis',
  part('CV Matcher'),
  '---',
  '## Cover letter',
  part('Cover Letter Writer'),
  '---',
  '## Interview preparation',
  part('Interview Coach'),
  '---',
  '_Generated by AI. Review and edit before you use it._',
].join('\n\n');
return { json: { markdown, name: prep.name, email: prep.email, missing } };
